import type { MetadataRoute } from 'next';

export default function manifest(): MetadataRoute.Manifest {
  return {
    name: 'Find My Doggo',
    short_name: 'Find My Doggo',
    description: 'A community noticeboard for lost and found dogs. Free to use, no account needed.',
    start_url: '/',
    scope: '/',
    display: 'standalone',
    // Paper and Terracotta ink (DESIGN.md → Colors). The icons are the collar
    // tag on paper, regenerated by `npm run brand:generate`.
    background_color: '#f9f8f5',
    theme_color: '#a34929',
    icons: [
      { src: '/android-chrome-192x192.png', sizes: '192x192', type: 'image/png' },
      { src: '/android-chrome-512x512.png', sizes: '512x512', type: 'image/png' },
      { src: '/android-chrome-512x512-maskable.png', sizes: '512x512', type: 'image/png', purpose: 'maskable' },
    ],
  };
}
